-- River Hub: re-derive sewage_systems for Dart from wastewater catchment areas. Idempotent.
begin;
create unique index if not exists sewage_systems_org_catchment_uniq on sewage_systems (organisation_id, catchment_identifier) where catchment_identifier is not null;
create temp table _wwc(identifier text, company text, name text, uww_code text, uww_name text, gj text) on commit drop;
delete from wastewater_catchments where organisation_id = '00000000-0000-0000-0000-000000000001'::uuid;
  select '00000000-0000-0000-0000-000000000001'::uuid, identifier, company, name, uww_code, uww_name,
         ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Transform(ST_SetSRID(ST_GeomFromGeoJSON(gj),27700),4326)),3))
  from _wwc;
create temp table _amap on commit drop as
select sa.id as asset_id, cc.identifier, coalesce(nullif(cc.uww_name,''), cc.name) as sysname,
       cc.uww_code, cc.conf
from sewage_assets sa
left join lateral (
  select c.identifier, c.uww_name, c.name, c.uww_code,
         case when ST_Contains(c.geom, p.geom) then 'high' else 'medium' end as conf
  from wastewater_catchments c,
       lateral (select ST_SetSRID(ST_MakePoint(sa.longitude, sa.latitude),4326) as geom) p
  where c.organisation_id = '00000000-0000-0000-0000-000000000001'::uuid
    and (ST_Contains(c.geom, p.geom)
         or ST_DWithin(c.geom::geography, p.geom::geography, 3000))
  order by (case when ST_Contains(c.geom, p.geom) then 0 else 1 end),
           ST_Distance(c.geom::geography, p.geom::geography)
  limit 1
) cc on true
where sa.organisation_id = '00000000-0000-0000-0000-000000000001'::uuid and sa.latitude is not null and sa.system_override is not true;
  select distinct '00000000-0000-0000-0000-000000000001'::uuid, sysname, uww_code, identifier, 'wwca' from _amap where identifier is not null
  on conflict (organisation_id, catchment_identifier) where catchment_identifier is not null
  do update set name = excluded.name, uww_code = excluded.uww_code, source = 'wwca';
update sewage_assets sa set sewage_system_id = s.id, system_match_confidence = m.conf
  from _amap m join sewage_systems s
    on s.organisation_id = '00000000-0000-0000-0000-000000000001'::uuid and s.catchment_identifier = m.identifier
  where sa.id = m.asset_id and m.identifier is not null;
update sewage_assets sa set system_match_confidence = 'low'
  from _amap m where sa.id = m.asset_id and m.identifier is null;
delete from sewage_systems s where s.organisation_id = '00000000-0000-0000-0000-000000000001'::uuid and s.catchment_identifier is null
  and not exists (select 1 from sewage_assets a where a.sewage_system_id = s.id)
  and not exists (select 1 from system_assumptions x where x.system_id = s.id);
select 'systems now: ' || count(*) from sewage_systems where organisation_id = '00000000-0000-0000-0000-000000000001'::uuid;
select 'assets high/medium/low: ' || count(*) filter (where system_match_confidence='high') || '/' || count(*) filter (where system_match_confidence='medium') || '/' || count(*) filter (where system_match_confidence='low') from sewage_assets where organisation_id = '00000000-0000-0000-0000-000000000001'::uuid;
commit;
